      pico: [R, 50, 116, 44, 'PICO 头显', C_VIS], gmr: [R + 148, 50, 124, 44, '重定向 100 Hz', C_VIS], redis: [R + 304, 50, 128, 44, 'Redis', C_ROOT],
      low: [R + 304, 130, 128, 44, '底层 50 Hz', C_WARN], g1: [R + 304, 210, 128, 44, 'G1 + ZED Mini', C_T2],
      gst: [R + 148, 210, 124, 44, 'GStreamer H.265', C_VIS], rec: [R, 210, 116, 44, '录数据 30 Hz', C_T2]
