  function nb(str) {
    return str.split(/(\$[^$]*\$)/).map(function (p, i) { return i % 2 ? p : p.replace(/(\d)(\*\*)? (?=[^\s\d+\-−→×<>=\/·（(])/g, '$1$2\u00a0').replace(/(\d)–(\d)/g, '$1–\u2060$2'); }).join('');
  }
